def sort_waste(items):
    """
    Групує список елементів за категоріями:
    "plastic", "glass", "paper", "organic".

    Кожен елемент може бути:
    - рядком, у якому присутнє слово‑ключ, що вказує на категорію,
    - словником з ключем 'category',
    - кортежем (value, category).

    Повертає словник {category: [елементи]}.
    """
    # Ключові слова, які визначають категорію
    keywords = {
        "plastic": {"plastic", "пластик", "пет"},
        "glass":   {"glass", "скло"},
        "paper":   {"paper", "папір", "картон"},
        "organic": {"organic", "органіка", "біо", "компост"},
    }

    # Підготовка результату
    result = {cat: [] for cat in keywords}
    result["unknown"] = []   # для елементів, які не вдалося класифікувати

    def detect_category(item):
        """Визначає категорію елемента за його типом."""
        # 1. Якщо це словник з явно вказаною категорією
        if isinstance(item, dict) and "category" in item:
            return str(item["category"]).lower()

        # 2. Якщо це кортеж (value, category)
        if isinstance(item, (list, tuple)) and len(item) == 2:
            return str(item[1]).lower()

        # 3. Якщо це рядок – шукаємо ключові слова
        if isinstance(item, str):
            lowered = item.lower()
            for cat, keys in keywords.items():
                if any(key in lowered for key in keys):
                    return cat
        # Не вдалося визначити
        return "unknown"

    for el in items:
        cat = detect_category(el)
        result.setdefault(cat, []).append(el)

    # Прибираємо порожню категорію "unknown", якщо вона порожня
    if not result["unknown"]:
        del result["unknown"]
    return result
