def sort_waste(items):
    """
    Групує список елементів за категоріями: пластик, скло, папір, органіка.
    Очікується, що кожен елемент у `items` – це кортеж (назва, категорія)
    або словник з ключем 'category'.

    Повертає словник виду:
        {
            'plastic':  [елементи],
            'glass':    [елементи],
            'paper':    [елементи],
            'organic':  [елементи],
        }
    """
    # ініціалізуємо порожні списки для всіх категорій
    result = {cat: [] for cat in ('plastic', 'glass', 'paper', 'organic')}

    for item in items:
        # визначаємо, як отримати назву та категорію
        if isinstance(item, dict):
            name = item.get('name')
            cat  = item.get('category')
        else:  # кортеж або інша ітерабельна послідовність
            try:
                name, cat = item
            except Exception:
                # якщо структура не підходить – пропускаємо елемент
                continue

        # нормалізуємо назву категорії
        if cat:
            cat = str(cat).strip().lower()
            # допускаємо короткі варіанти назв
            if cat in ('plastic', 'plastik', 'пластик'):
                result['plastic'].append(name)
            elif cat in ('glass', 'sklo', 'скло'):
                result['glass'].append(name)
            elif cat in ('paper', 'paper', 'папір'):
                result['paper'].append(name)
            elif cat in ('organic', 'organika', 'органіка'):
                result['organic'].append(name)
            else:
                # елемент з невідомою категорією – ігноруємо або можна
                # додати в окрему групу, наприклад 'unknown'
                pass

    return result
